public static class AVADocuRefExtensionDelegates
{
}

Method.Source:
/// <summary>
/// delegate for method OnInsert in class DocuRefExtension
/// </summary>
/// <param name = "_docuRef">DocuRef</param>
/// <param name = "_interCompanyFromRecId">InterCompanyFromRecId</param>
[SubscribesTo(classStr(DocuRefExtension), delegateStr(DocuRefExtension,OnInsert ))]
public static void DocuRefOnInsert(DocuRef _docuRef, RecId _interCompanyFromRecId)
{
    KCS_TCVGroup    tcvGroup;

    if (_docuRef.KCS_TCVGroupId)
    {
        tcvGroup = KCS_TCVGroup::find(_docuRef.KCS_TCVGroupId);
        if (tcvGroup.DocuTypeId)
        {
            _docuRef.TypeId = tcvGroup.DocuTypeId;
            _docuRef.KCS_TCVinitFromDocuType();
        }
    }
}

[SubscribesTo(classStr(DocuRefExtension), delegateStr(DocuRefExtension,OnPostInsert ))]
public static void DocuRefPostInsert(DocuRef _docuRef, RecId _interCompanyFromRecId)
{
    AVADocuRestrictionReference         docuRestrictionReference;

    select firstonly docuRestrictionReference
        where docuRestrictionReference.DocuRefRecId == _docuRef.RecId;

    if (!docuRestrictionReference && _docuRef.RecId)
    {
        AVADocuRestriction          avaDocuRestriction;
        select firstonly avaDocuRestriction
            order by Num;
        docuRestrictionReference.DocuRefRecId = _docuRef.RecId;
        docuRestrictionReference.DocuRestrictionNum = avaDocuRestriction.Num;
        docuRestrictionReference.insert();

    }
}
